/* Optional original frame treatments: pure CSS, independently loadable.
   Pair .syn-frame with exactly one shape modifier. No canvas, images or JS.
   The cut shapes paint their own outlines; they do not mask the host's parent. */
@layer syn.geometry {
  /* All component rules match the root itself or a descendant, never a host sibling. */
  :where(.syn-root, .syn-root *) {
    &.syn-frame {
      position: relative;
      z-index: 0;
      isolation: isolate;
      min-width: 0;
      border: 0;
      border-radius: 0;
      background: transparent;
      color: var(--syn-text);
      /* User controls inherit: legacy --syn-frame-cut remains the fallback. */
      --_syn-outer-tl: var(--syn-frame-cut-tl, var(--syn-frame-cut, 1rem));
      --_syn-outer-tr: var(--syn-frame-cut-tr, var(--syn-frame-cut, 1rem));
      --_syn-outer-br: var(--syn-frame-cut-br, var(--syn-frame-cut, 1rem));
      --_syn-outer-bl: var(--syn-frame-cut-bl, var(--syn-frame-cut, 1rem));
      /* For a 45-degree bevel, subtract (2 - sqrt(2)) * stroke from the
         inner cut. This keeps diagonal and orthogonal ring widths closer.
         Use a positive cut >= stroke; stepped shapes keep square offsets. */
      --_syn-inner-tl: max(0px, calc(var(--_syn-outer-tl) - var(--syn-frame-stroke, 1px) * 0.585786));
      --_syn-inner-tr: max(0px, calc(var(--_syn-outer-tr) - var(--syn-frame-stroke, 1px) * 0.585786));
      --_syn-inner-br: max(0px, calc(var(--_syn-outer-br) - var(--syn-frame-stroke, 1px) * 0.585786));
      --_syn-inner-bl: max(0px, calc(var(--_syn-outer-bl) - var(--syn-frame-stroke, 1px) * 0.585786));
    }
    &.syn-frame::before,
    &.syn-frame::after {
      content: "";
      position: absolute;
      pointer-events: none;
      z-index: -1;
      inset: 0;
      /* Reset dimensions/clips left by earlier-layer panel decorations. */
      width: auto;
      height: auto;
      clip-path: none;
    }
    /* Shape-independent accent emphasis adds no pseudo-elements. */
    &.syn-frame--accent {
      --syn-frame-outline: var(--syn-accent);
      --syn-frame-stroke: 2px;
    }
    /* A shape owns both pseudo-elements. The outer layer draws a paintable
       perimeter; the inner layer is inset and exposes the border ring. */
    &.syn-frame--bevel {
      --syn-frame-shape: polygon(
        var(--_syn-outer-tl) 0,
        calc(100% - var(--_syn-outer-tr)) 0,
        100% var(--_syn-outer-tr),
        100% calc(100% - var(--_syn-outer-br)),
        calc(100% - var(--_syn-outer-br)) 100%,
        var(--_syn-outer-bl) 100%,
        0 calc(100% - var(--_syn-outer-bl)),
        0 var(--_syn-outer-tl));
      --_syn-inner-shape: polygon(
        var(--_syn-inner-tl) 0,
        calc(100% - var(--_syn-inner-tr)) 0,
        100% var(--_syn-inner-tr),
        100% calc(100% - var(--_syn-inner-br)),
        calc(100% - var(--_syn-inner-br)) 100%,
        var(--_syn-inner-bl) 100%,
        0 calc(100% - var(--_syn-inner-bl)),
        0 var(--_syn-inner-tl));
    }
    &.syn-frame--notch {
      --syn-frame-shape: polygon(
        0 0,
        calc(100% - var(--_syn-outer-tr)) 0,
        100% var(--_syn-outer-tr),
        100% 100%,
        var(--_syn-outer-bl) 100%,
        0 calc(100% - var(--_syn-outer-bl)));
      --_syn-inner-shape: polygon(
        0 0,
        calc(100% - var(--_syn-inner-tr)) 0,
        100% var(--_syn-inner-tr),
        100% 100%,
        var(--_syn-inner-bl) 100%,
        0 calc(100% - var(--_syn-inner-bl)));
    }
    &.syn-frame--step {
      --syn-frame-shape: polygon(
        0 0,
        calc(100% - var(--_syn-outer-tr)) 0,
        calc(100% - var(--_syn-outer-tr)) calc(var(--_syn-outer-tr) / 2),
        calc(100% - calc(var(--_syn-outer-tr) / 2)) calc(var(--_syn-outer-tr) / 2),
        calc(100% - calc(var(--_syn-outer-tr) / 2)) var(--_syn-outer-tr),
        100% var(--_syn-outer-tr),
        100% 100%,
        var(--_syn-outer-bl) 100%,
        var(--_syn-outer-bl) calc(100% - calc(var(--_syn-outer-bl) / 2)),
        calc(var(--_syn-outer-bl) / 2) calc(100% - calc(var(--_syn-outer-bl) / 2)),
        calc(var(--_syn-outer-bl) / 2) calc(100% - var(--_syn-outer-bl)),
        0 calc(100% - var(--_syn-outer-bl)));
      --_syn-inner-shape: var(--syn-frame-shape);
    }
    &.syn-frame--facet {
      --syn-frame-shape: polygon(
        var(--_syn-outer-tl) 0,
        100% 0,
        100% calc(100% - var(--_syn-outer-br)),
        calc(100% - var(--_syn-outer-br)) 100%,
        0 100%,
        0 var(--_syn-outer-tl));
      --_syn-inner-shape: polygon(
        var(--_syn-inner-tl) 0,
        100% 0,
        100% calc(100% - var(--_syn-inner-br)),
        calc(100% - var(--_syn-inner-br)) 100%,
        0 100%,
        0 var(--_syn-inner-tl));
    }
    &.syn-frame--bevel::before, &.syn-frame--notch::before,
    &.syn-frame--step::before, &.syn-frame--facet::before {
      clip-path: var(--syn-frame-shape);
      background: var(--syn-frame-border-paint, var(--syn-frame-outline, var(--syn-frame-strong)));
    }
    &.syn-frame--bevel::after, &.syn-frame--notch::after,
    &.syn-frame--step::after, &.syn-frame--facet::after {
      inset: var(--syn-frame-stroke, 1px);
      clip-path: var(--_syn-inner-shape);
      /* Optional overlay follows the inner shape. No extra markup is required. */
      background: var(--syn-frame-inlay-paint, linear-gradient(transparent, transparent)),
                  var(--syn-frame-fill, var(--syn-surface));
    }
    /* Brackets don't obscure the content or assume an enclosing background. */
    &.syn-frame--bracket::before {
      background: var(--syn-frame-fill, var(--syn-surface));
    }
    &.syn-frame--bracket::after {
      --syn-bracket-size: clamp(.75rem, var(--syn-frame-cut, 1rem), 1.5rem);
      background:
        linear-gradient(var(--syn-accent), var(--syn-accent)) top left / var(--syn-bracket-size) var(--syn-frame-stroke, 1px) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) top left / var(--syn-frame-stroke, 1px) var(--syn-bracket-size) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) top right / var(--syn-bracket-size) var(--syn-frame-stroke, 1px) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) top right / var(--syn-frame-stroke, 1px) var(--syn-bracket-size) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) bottom left / var(--syn-bracket-size) var(--syn-frame-stroke, 1px) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) bottom left / var(--syn-frame-stroke, 1px) var(--syn-bracket-size) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) bottom right / var(--syn-bracket-size) var(--syn-frame-stroke, 1px) no-repeat,
        linear-gradient(var(--syn-accent), var(--syn-accent)) bottom right / var(--syn-frame-stroke, 1px) var(--syn-bracket-size) no-repeat;
    }
    /* Inner technical framing with no additional DOM elements. */
    &.syn-frame--inset::before {
      border: var(--syn-frame-stroke, 1px) solid var(--syn-frame-outline, var(--syn-frame-strong));
      background: var(--syn-frame-fill, var(--syn-surface));
    }
    &.syn-frame--inset::after {
      inset: .45rem;
      border: var(--syn-frame-stroke, 1px) solid var(--syn-accent);
      opacity: .55;
    }
    &.syn-frame--circuit::before {
      border: var(--syn-frame-stroke, 1px) solid var(--syn-frame-outline, var(--syn-frame-strong));
      background: var(--syn-frame-fill, var(--syn-surface));
    }
    &.syn-frame--circuit::after {
      background:
        linear-gradient(var(--syn-accent),var(--syn-accent)) top left / 38% 2px no-repeat,
        linear-gradient(var(--syn-accent),var(--syn-accent)) top left / 2px 28% no-repeat,
        linear-gradient(var(--syn-accent),var(--syn-accent)) bottom right / 28% 2px no-repeat,
        linear-gradient(var(--syn-accent),var(--syn-accent)) bottom right / 2px 38% no-repeat;
    }
    @media (forced-colors: active) {
      &.syn-frame {
        border: 1px solid CanvasText;
        background: Canvas;
        color: CanvasText;
      }
      &.syn-frame::before, &.syn-frame::after { display: none; }
    }
  }
}
